import{_ as t,l as i,o as a,c as n,v as o,p as s,x as l,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"rollout 引擎与权重同步","description":"","frontmatter":{"title":"rollout 引擎与权重同步","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rollout-weight-sync.md","filePath":"llm/rollout-weight-sync.md","lastUpdated":1789023840000}'),c={name:"llm/rollout-weight-sync.md"};function _(m,e,u,g,b,f){const r=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="rollout-引擎与权重同步" tabindex="-1">rollout 引擎与权重同步 <a class="header-anchor" href="#rollout-引擎与权重同步" aria-label="Permalink to &quot;rollout 引擎与权重同步&quot;">​</a></h1><div class="epigraph"><p>生成用推理引擎、训练用 Megatron，中间那条权重边的延迟与一致性，决定 logprob 还能不能当 π_old。</p><footer>—— 对照 HybridFlow 的重切分、vLLM / SGLang 作为 rollouter、OpenRLHF 与 verl 的广播与 sleep 模式</footer></div><p><a href="/llm/off-policy-correction">上一课</a>要求每条轨迹有可信的 \\(\\log\\pi_{\\mathrm{beh}}\\)。缺口落到系统：<strong>推理引擎里的权重是不是 learner 刚推送的那一份，精度与模板是否一致。</strong> 异步架构课写时序契约；本课写同步边上的工程：广播、sleep 共置、重算。算法仍是 <a href="/llm/ppo-llm">PPO</a> / <a href="/llm/grpo">GRPO</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>训练布局（FSDP / Megatron 切分）与生成布局（TP + paged KV）不同。每次更新后要把 \\(\\theta\\) 变成生成引擎可加载的副本。共置 sleep：同一组 GPU 时分复用，权重切分转换，延迟低、实现重。分置：learner 训练、rollouter 常驻，NCCL / 参数服务器广播，生成可持续，但推送瞬间版本跃迁。推送频率低，staleness 升；频率高，气泡升。</p><p>失败模式：引擎仍用旧权生成，却把当前 \\(\\theta\\) 的 logprob 当成 \\(\\pi_{\\mathrm{beh}}\\)——IS 全错。或生成用 chat 模板 A，训练前向用模板 B，奖励打在另一字符串上。</p><h3 id="缓存的-logprob-属于哪一版" tabindex="-1">缓存的 logprob 属于哪一版 <a class="header-anchor" href="#缓存的-logprob-属于哪一版" aria-label="Permalink to &quot;缓存的 logprob 属于哪一版&quot;">​</a></h3><p>生成时应在<strong>同一次前向</strong>里记下 \\(\\log\\pi_{\\mathrm{beh}}\\)，与发出的 token 对齐，含温度、top-\\(p\\) 是否作用于采样但不作用于要存储的裸 logprob。存储裸 \\(\\log\\pi\\)（softmax 前的分布对数），采样约束另记。训练重算必须关 dropout、对齐精度。</p><p><span class="marginnote">LoRA 只同步 A/B 矩阵时，基座必须双方锁定同一份。漏同步一份 adapter，就是静默 off-policy。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小协议：<code>sync_id</code> 单调递增；rollouter 加载成功才接受新请求；正在解码的序列要么跑完旧版，要么中断重算 KV。Learner 在 <code>sync_id</code> 写入样本元数据。评测路径与训练生成共用同一引擎配置。重切分（3D-HybridEngine）把训练切分转成推理切分，避免 CPU 落盘。</p>',11)),(a(),s(h,null,{default:l(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20L%5B%22Learner%20%CE%B8%22%5D%20--%3E%20S%5B%22sync_id%20%E5%B9%BF%E6%92%AD%20%2F%20%E9%87%8D%E5%88%87%E5%88%86%22%5D%0A%20%20S%20--%3E%20R%5B%22Rollouter%20%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20R%20--%3E%20Y%5B%22%E9%87%87%E6%A0%B7%20y%20%2B%20log%CF%80_beh%22%5D%0A%20%20Y%20--%3E%20Q%5B%22%E5%B8%A6%20sync_id%20%E5%85%A5%E9%98%9F%22%5D%0A%20%20Q%20--%3E%20L%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与奖励模型同步：RM 冻结则少一条边；RM 迭代时要第二份 <code>sync_id</code>，否则策略与裁判版本错位，像在优化旧口味。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>权重边的延迟进入 staleness \\(\\eta\\)。数学上 \\(\\eta\\) 已在上一课定义；本课决定 \\(\\eta\\) 的物理下限：广播 70B 权重要多少毫秒。部分同步（只推 embedding）会造成层间版本撕裂，比整网落后一拍更难校正。要么全量原子换，要么明确冻结哪些层。</p><p><span class="marginnote">CUDA graph / 编译缓存按形状绑定。换权后必须使缓存失效。旧 graph 跑新权是未定义行为。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>小模型共置同步更简单，不必上参数服务器。长链推理才值得分置。MoE 还要同步路由专家，漏专家比漏一层更致命。同步完成应以 rollouter 的校验哈希为准，不要信发送端「已推送」。下一课采样温度：即使权重一致，解码随机性仍改变 \\(\\pi_{\\mathrm{beh}}\\) 的定义——温度是策略的一部分，不是 UI。</p><p>sync_id 要以 rollouter 加载成功为准；模板、LoRA、MoE 专家漏同步会让比率在版本号正确时仍然全错。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>训练与生成之间的权重同步必须原子、带 sync_id，logπ_beh 与该版对齐。</li><li>共置重切分延迟低；分置广播吞吐高、staleness 要配额。</li><li>模板、LoRA、MoE 专家漏同步 = 静默错误 IS。</li><li>RM 若迭代，裁判也要版本号。</li><li>出处：Sheng 等 HybridFlow；OpenRLHF / verl / slime 的 rollouter 实践。</li></ul>',9))])}const P=t(c,[["render",_]]);export{A as __pageData,P as default};
